function bestHaul(nums: number[]): number {
  const n = nums.length;
  const dp = new Array<number>(n + 1).fill(0); // dp[k] = best from the first k stalls
  dp[1] = nums[0];
  for (let k = 2; k <= n; k++) dp[k] = Math.max(dp[k - 1], dp[k - 2] + nums[k - 1]);
  return dp[n];
}

